import { htmlToText } from '../audit-engine/checks/shared/html.js';
import { isLiveAt, splitByPublication } from '../audit-engine/checks/shared/published.js';
import type { StoreSnapshot } from '../audit-engine/store-data/types.js';

/**
 * ─── llms.txt / agents.md generation ─────────────────────────────────
 * Builds the two agent-facing files from what the store ACTUALLY contains.
 *
 * ─── DETERMINISTIC, NOT GENERATED BY A MODEL ─────────────────────────
 * No AI is involved and none should be. Every line of output is either a real field from the
 * merchant's catalogue or fixed structural text. A model asked to "write an llms.txt for a coffee
 * roaster" produces plausible sentences about shipping windows and roast profiles that the store
 * never stated — and the merchant would then publish those invented claims at their own domain, to
 * be read by assistants, as fact. That failure mode is the whole reason this is a template fed by
 * real data rather than a prompt.
 *
 * The consequence is visible and intended: a thin catalogue produces a thin file. Where the store
 * has no data, the file says nothing rather than filling the gap.
 *
 * ─── CONTENT ONLY. THIS DOES NOT PUBLISH. ────────────────────────────
 * The output is text for the merchant to publish themselves. Rankvora AI has no app proxy and no theme
 * extension, so it cannot serve a file at a merchant's storefront root — and the audit's
 * `agents-md` check verifies by really requesting the URL, so a file that was never published will
 * be reported missing no matter what was generated here. Generation and verification stay honestly
 * separate.
 *
 * Format follows the llms.txt convention: an H1 name, a blockquote summary, then H2 sections of
 * link lists with a short description after each link.
 */

/** Products listed in llms.txt. Beyond this the file stops being a summary. */
const PRODUCT_LIMIT = 100;

/** Products listed in the long-form variant, which is meant to be exhaustive-ish. */
const FULL_PRODUCT_LIMIT = 1_000;

const COLLECTION_LIMIT = 50;

/** One-line product blurb length. Long enough to be useful, short enough to stay a list. */
const BLURB_CHARS = 160;

export interface GeneratedFile {
  /** The path this file is meant to be published at, relative to the storefront root. */
  path: string;
  content: string;
  /** Bytes the merchant will be publishing. Shown so a large catalogue's file size is visible. */
  bytes: number;
  /** What was actually included, so nothing about the output is a mystery. */
  includes: string[];
  /** Real data the store does not have, which is why the file omits those sections. */
  omitted: string[];
}

/**
 * The link to write for a resource: root-relative when it lives on the storefront, absolute when
 * it does not.
 *
 * Every URL used to be cut down to its path. That is right for products and collections, which
 * live on the store, and wrong for anything that does not: Shopify can answer a policy's URL on a
 * different host, and stripping that host turned it into a path on the storefront — a link the
 * file published that pointed somewhere the policy is not.
 */
function linkFor(url: string, storefrontOrigin: string): string {
  try {
    const parsed = new URL(url);
    const storefront = new URL(storefrontOrigin);
    return parsed.host === storefront.host ? `${parsed.pathname}${parsed.search}` : parsed.toString();
  } catch {
    return url;
  }
}

/** First sentence-ish of a description, flattened to one line. Never invented. */
function blurb(html: string, limit = BLURB_CHARS): string {
  const text = htmlToText(html);
  if (!text) return '';
  if (text.length <= limit) return text;
  // Cut at a word boundary so the line does not end mid-word.
  const cut = text.slice(0, limit);
  const lastSpace = cut.lastIndexOf(' ');
  return `${(lastSpace > limit * 0.6 ? cut.slice(0, lastSpace) : cut).trim()}…`;
}

/** `- [Title](/path): blurb`, with the colon omitted when there is no blurb to follow it. */
function listItem(title: string, link: string, description: string): string {
  const text = description.trim();
  return text ? `- [${title}](${link}): ${text}` : `- [${title}](${link})`;
}

/**
 * What the files are built from: only resources a visitor can reach.
 *
 * The snapshot holds drafts, archived products and unpublished pages too. Listing those would
 * publish, at the merchant's own domain, links that answer 404 — and describe products the store
 * does not sell. Products use the shared publication rule the audit checks use; pages must be
 * published by the time the snapshot was read.
 */
type LiveContent = ReturnType<typeof liveContent>;

function liveContent(snapshot: StoreSnapshot) {
  const { published, unpublished } = splitByPublication(snapshot.products);
  return {
    products: published.filter((product) => product.title.trim()),
    unpublishedProducts: unpublished,
    pages: snapshot.pages.filter((page) => page.title.trim() && isLiveAt(page.publishedAt, snapshot.capturedAt)),
  };
}

/**
 * The store's own summary line.
 *
 * Built ONLY from fields the merchant filled in. When there is nothing to say, the blockquote is
 * omitted entirely rather than filled with "A Shopify store selling quality products" — a
 * sentence that is true of every store and therefore information about none.
 */
function summaryLine(snapshot: StoreSnapshot, live: LiveContent): string | null {
  const parts: string[] = [];
  // From what is on sale: a category that exists only on draft products is not something the
  // store sells, and a brand carried only by archived stock is not one it carries.
  const types = [...new Set(live.products.map((product) => product.productType.trim()).filter(Boolean))];
  const vendors = [...new Set(live.products.map((product) => product.vendor.trim()).filter(Boolean))];

  if (types.length > 0) {
    parts.push(`Sells ${types.slice(0, 5).join(', ')}${types.length > 5 ? ` and ${types.length - 5} other categories` : ''}.`);
  }
  if (vendors.length === 1) parts.push(`All products are ${vendors[0]}.`);
  else if (vendors.length > 1) parts.push(`Carries ${vendors.length} brands.`);
  if (snapshot.shop.country) parts.push(`Based in ${snapshot.shop.country}.`);
  if (snapshot.shop.currency) parts.push(`Prices in ${snapshot.shop.currency}.`);

  return parts.length > 0 ? parts.join(' ') : null;
}

/** "1 policy", "3 policies" — the counts in `includes` are read by the merchant. */
function plural(count: number, one: string, many: string): string {
  return `${count} ${count === 1 ? one : many}`;
}

function buildLlmsTxt(snapshot: StoreSnapshot, live: LiveContent, productLimit: number, includeBodies: boolean): GeneratedFile {
  const includes: string[] = [];
  const omitted: string[] = [];
  const lines: string[] = [`# ${snapshot.shop.name}`, ''];
  const link = (url: string) => linkFor(url, snapshot.shop.primaryUrl);

  const summary = summaryLine(snapshot, live);
  if (summary) {
    lines.push(`> ${summary}`, '');
    includes.push('Store summary derived from product types, vendors and shop settings');
  } else {
    omitted.push('Store summary — no product types or vendors are set, so there was nothing factual to summarise');
  }

  // ── Collections ──
  const collections = snapshot.collections.filter((collection) => collection.title.trim());
  if (collections.length > 0) {
    lines.push('## Collections', '');
    for (const collection of collections.slice(0, COLLECTION_LIMIT)) {
      lines.push(listItem(collection.title, link(collection.url), blurb(collection.bodyHtml)));
    }
    if (collections.length > COLLECTION_LIMIT) {
      lines.push(`- ${collections.length - COLLECTION_LIMIT} further collections are listed in the sitemap.`);
    }
    lines.push('');
    includes.push(plural(Math.min(collections.length, COLLECTION_LIMIT), 'collection', 'collections'));
  } else {
    omitted.push('Collections — this store has none Rankvora AI could read');
  }

  // ── Products ──
  const products = live.products;
  if (products.length > 0) {
    lines.push('## Products', '');
    for (const product of products.slice(0, productLimit)) {
      const facts: string[] = [];
      if (product.productType.trim()) facts.push(product.productType.trim());
      if (product.vendor.trim()) facts.push(product.vendor.trim());
      const description = includeBodies ? blurb(product.bodyHtml, 400) : blurb(product.bodyHtml);
      const prefix = facts.length > 0 ? `${facts.join(' · ')}${description ? '. ' : ''}` : '';
      lines.push(listItem(product.title, link(product.url), `${prefix}${description}`));
    }
    if (products.length > productLimit) {
      lines.push('', `${products.length - productLimit} further products are listed in the store sitemap at /sitemap.xml.`);
    }
    lines.push('');
    includes.push(`${Math.min(products.length, productLimit)} of ${plural(products.length, 'published product', 'published products')}`);
    if (products.length > productLimit) {
      omitted.push(`${products.length - productLimit} products beyond the ${productLimit}-item cap — the file points to the sitemap for the rest`);
    }
  } else {
    omitted.push(
      live.unpublishedProducts > 0
        ? 'Products — none of this store’s products are published to the online store'
        : 'Products — this store has none Rankvora AI could read',
    );
  }
  if (live.unpublishedProducts > 0) {
    omitted.push(`${plural(live.unpublishedProducts, 'draft, archived or unpublished product', 'draft, archived or unpublished products')} — not on your storefront, so linking ${live.unpublishedProducts === 1 ? 'it' : 'them'} would publish a page that answers 404`);
  }

  // ── Pages and policies ──
  const pages = live.pages;
  if (pages.length > 0) {
    lines.push('## Pages', '');
    for (const page of pages.slice(0, COLLECTION_LIMIT)) {
      lines.push(listItem(page.title, link(page.url), blurb(page.bodyHtml)));
    }
    lines.push('');
    includes.push(plural(Math.min(pages.length, COLLECTION_LIMIT), 'page', 'pages'));
  }

  const policies = snapshot.policies.filter((policy) => policy.url && policy.body.trim());
  if (policies.length > 0) {
    lines.push('## Policies', '');
    for (const policy of policies) {
      lines.push(listItem(policy.title, link(policy.url as string), blurb(policy.body)));
    }
    lines.push('');
    includes.push(plural(policies.length, 'shop policy', 'shop policies'));
  } else {
    omitted.push(
      snapshot.policyAccess.available
        ? 'Policies — this store publishes none'
        : 'Policies — Rankvora AI was not granted read_legal_policies, so they could not be read',
    );
  }

  const content = `${lines.join('\n').replace(/\n{3,}/g, '\n\n').trim()}\n`;
  return {
    path: includeBodies ? '/llms-full.txt' : '/llms.txt',
    content,
    bytes: Buffer.byteLength(content, 'utf8'),
    includes,
    omitted,
  };
}

/**
 * agents.md — a shorter, instruction-shaped file pointing at the machine-readable resources.
 *
 * It deliberately does NOT restate the catalogue: llms.txt already does that, and two files
 * carrying the same list is two files to keep in step. What it adds is where to look and who to
 * contact, both from real shop data.
 */
function buildAgentsMd(snapshot: StoreSnapshot, live: LiveContent): GeneratedFile {
  const includes: string[] = [];
  const omitted: string[] = [];
  const lines: string[] = [`# ${snapshot.shop.name} — Agent Guide`, ''];

  const summary = summaryLine(snapshot, live);
  if (summary) {
    lines.push(summary, '');
    includes.push('Store summary derived from real catalogue fields');
  }

  lines.push(
    '## Structured data',
    '',
    '- Sitemap: /sitemap.xml',
    '- Catalogue summary: /llms.txt',
  );
  includes.push('Pointers to the sitemap and llms.txt');

  const policies = snapshot.policies.filter((policy) => policy.url);
  if (policies.length > 0) {
    lines.push('');
    lines.push('## Policies', '');
    for (const policy of policies) lines.push(`- ${policy.title}: ${linkFor(policy.url as string, snapshot.shop.primaryUrl)}`);
    includes.push(plural(policies.length, 'policy link', 'policy links'));
  }

  if (snapshot.shop.email) {
    lines.push('', '## Contact', '', snapshot.shop.email);
    includes.push('Shop contact email');
  } else {
    omitted.push('Contact — no shop email is set in Shopify');
  }

  const content = `${lines.join('\n').replace(/\n{3,}/g, '\n\n').trim()}\n`;
  return {
    path: '/agents.md',
    content,
    bytes: Buffer.byteLength(content, 'utf8'),
    includes,
    omitted,
  };
}

export interface GeneratedAgentFiles {
  llmsTxt: GeneratedFile;
  llmsFullTxt: GeneratedFile;
  agentsMd: GeneratedFile;
  /** What the files were built from, so the merchant can judge how complete they are. */
  source: {
    /** Published products — the ones the files list. */
    products: number;
    /** Products read but left out: draft, archived or not on the online store. */
    unpublishedProducts: number;
    collections: number;
    /** Published pages — the ones the files list. */
    pages: number;
    policies: number;
    productsTruncated: boolean;
    capturedAt: string;
  };
}

/** All three files, from one snapshot of the real store. */
export function generateAgentFiles(snapshot: StoreSnapshot): GeneratedAgentFiles {
  const live = liveContent(snapshot);
  return {
    llmsTxt: buildLlmsTxt(snapshot, live, PRODUCT_LIMIT, false),
    llmsFullTxt: buildLlmsTxt(snapshot, live, FULL_PRODUCT_LIMIT, true),
    agentsMd: buildAgentsMd(snapshot, live),
    source: {
      products: live.products.length,
      unpublishedProducts: live.unpublishedProducts,
      collections: snapshot.collections.length,
      pages: live.pages.length,
      policies: snapshot.policies.length,
      productsTruncated: snapshot.scope.productsTruncated,
      capturedAt: snapshot.capturedAt.toISOString(),
    },
  };
}
